If $k$ is odd, assuming $f\T{k}>0$ for simplicity, we have
\begin{align*}
    x_0 &= \Bar{x}-\epsilon, \\
    f'(x_0) &= -f''\epsilon + \frac{1}{(k-1)!}f\T{k}\epsilon^{k-1}-\frac{1}{k!}f\T{k+1}\epsilon^k + \mathcal{O}(\epsilon^{k+1}),\\
    x_1 &= x_0-\eta f'(x_0) = \Bar{x}-\epsilon +\eta f''\epsilon - \frac{1}{(k-1)!}\eta f\T{k}\epsilon^{k-1}+\frac{1}{k!}\eta f\T{k+1}\epsilon^k  + \mathcal{O}(\epsilon^{k+1}),\\
    f'(x_1) &= f''\cdot(x_1-\Bar{x})+\frac{1}{(k-1)!}f\T{k}\cdot(x_1-\Bar{x})^{k-1}+\frac{1}{k!}f\T{k+1}\cdot(x_1-\Bar{x})^{k}+\mathcal{O}(\epsilon^{k+1}), \\
    \frac{x_2-x_0}{\eta} &= \frac{x_1-\eta f'(x_1)-x_0}{\eta} =-f'(x_0)-f'(x_1) \\
    &= \left(2f''-\eta f''f''\right)\epsilon \\
    &~ +\left(-\frac{1}{(k-1)!}f\T{k}+\frac{1}{(k-1)!}\eta f''f\T{k}-\frac{1}{(k-1)!}f\T{k}\cdot(-1+\eta f'')^{k-1}\right)\epsilon^{k-1}\\
    &~ +\left(\frac{1}{k!}f^{k+1}-\frac{1}{k!}\eta f'' f\T{k+1}-\frac{1}{k!}f\T{k+1}\cdot(-1+\eta f'')^k\right)\epsilon^k + \mathcal{O}(\epsilon^{k+1})
\end{align*}
When $\eta=\frac{2}{f''}$, it holds
\begin{align}
    \frac{x_2-x_0}{\eta}=-\frac{2}{k!}f\T{k+1}\epsilon^k+ \mathcal{O}(\epsilon^{k+1}).\label{eq:temp1}
\end{align}


When $\eta=\frac{2}{f''-f\T{k}\epsilon^{k-2}}$ then $\eta f''=2+2\frac{f\T{k}}{f''}\epsilon^{k-2}+\mathcal{O}(\epsilon^{2k-4})$, then it holds
\begin{align}
    \frac{x_2-x_0}{\eta}=-2f\T{k}\epsilon^{k-1}+\mathcal{O}(\epsilon^k).\label{eq:temp2}
\end{align}


Since $k$ is odd and $\epsilon\cdot f\T{k}(\Bar{x})>0, f\T{k+1}(\Bar{x})<0$, the above two estimations of $\nicefrac{x_2-x_0}{\eta}$ have one positive and one negative exactly. Therefore, due to the continuity of $x_2-x_0$ wrt $\eta$, there exists a learning rate $\eta\in(\frac{2}{f''}, \frac{2}{f''-f\T{k}\epsilon^{k-2}})$ such that $x_2=x_0$.

The above proof can be generalized to any $x_0$ between $\Bar{x}$ and $\Bar{x}-\epsilon$ with the same bound for $\eta$.

(2)
If $k$ is even, we have
\begin{align*}
    x_0 &= \Bar{x}-\epsilon, \\
    f'(x_0) &= -f''\epsilon - \frac{1}{(k-1)!}f\T{k}\epsilon^{k-1} + \mathcal{O}(\epsilon^{k}),\\
