\end{align*}
where the second inequality is due to $v\le 5w$ and $v\ge w_y$. Since $w^{(t+1)}\ge w^{(t)}$ (due to $A>0$) in this stage, we have $v^{(t+1)}\le 5w_x^{(t+1)}$.

Combining the above discussion, we have prove (\ref{eq:ratiowx}). Obviously, when $w_y/w_x\le 2.7$, RHS of (\ref{eq:ratiowx}) is at least $0.55$, larger than $1.1/\pi$, which is the upper bound of the $\Delta w_y/w_y$. As a result, $w_y/w_x$ keeps decreasing.

The next step is to show the growing ratio of $v w_x$ is much larger than that of $w_y$. From (\ref{eq:deltawx}, \ref{eq:deltawy}), it holds
\begin{align*}
    v^{(t+1)} w_x^{(t+1)} &= (v+\Delta v)(w_x+\Delta w_x) \ge v w_x + KA(v^2+ w_x^2) + K^2 A^2 v w_x \\
    &\ge vw_x(1+A)^2,
\end{align*}
where the first inequality is due to $\Delta w_y\ge0$. It follows $v^{(t+1)} w_x^{(t+1)}/v^{(t)} w_x^{(t)}\ge 1.6^2=2.56$.

So far, we have shown the following facts: under the defined initialization at time 0, starting from time 1, we have
\begin{enumerate}
    \item $v w_x\le 1/2\pi$.
    \item $\Delta w_x/w_x+1\ge 1.55$.
    \item $\Delta w_y/w_y+1\le 1+K/\pi$.
    \item $w_y/w_x \le 2.7$ and keeps decreasing.
    \item $v^{(t+1)} w_x^{(t+1)}/v^{(t)} w_x^{(t)}\ge 2.56$.
    \item $v\ge w_y$.
    \item $v\Delta w_y<(\Delta w_x)^2$.
\end{enumerate}

Now we are to use the above facts to bound $v w_x, w_y$ and $v-w_x$ to the end of stage 1.

For $v w_x$, in previous discussion, we have shown that $v w_x\le \frac{1}{2\pi}$. Actually, there is another special value
\begin{align}
    \frac{w_x w_y}{\pi(w_x^2+w_y^2)} = 0.104 \text{  when $w_y/w_x=2.7.$}
\end{align}
This value is slightly larger than $1/4\pi$. Hence, we would like to split the analysis into three parts: in the \textbf{first step of stage 2}, 
\begin{enumerate}
    \item $v w_x\ge \frac{1}{2\pi}$.
    \item $\frac{1}{4\pi}\le v w_x<\frac{1}{2\pi}$.
    \item $v w_x<\frac{1}{4\pi}$.
\end{enumerate}

Note that, although we are discussing the stage 1 in this section, investigating the lower bound of the first step in stage 2 helps calculate the number of iterations in stage 1. Furthermore, it helps bound several variables in stage 1.

\textbf{Case (I). If $vw_x\ge\frac{1}{2\pi}$ in first step of stage 2:}

Since we have prove $\frac{v\T{1} w_x\T{1}}{(w_y\T{1})^2}\ge1/2.7$ and $v^{(t+1)} w_x^{(t+1)}/v^{(t)} w_x^{(t)}\ge 2.56$, the number of iterations for $vw_x$ to reach $1/2\pi$ is at most
\begin{align}
    T_1\le \left\lceil\log_{2.56}\frac{\frac{1}{2\pi}}{(w_y\T{1})^2/2.7}\right\rceil. \label{eq:T1}
\end{align}
Meanwhile, starting from time 1, the growth ratio of $w_y$ is
\begin{align}
    (w_y + \Delta w_y)/w_y\le 1+K(-v^2+1/\pi)\le 1+1.1/\pi-(v\T{1})^2\le 1+1.1/\pi-(w_y\T{1})^2,
\end{align}
where the first inequality is due to $vw_y\le\norm{w}^2$, the second is due to $K>1$ and the third is from $v\ge w_y$. Therefore, combining with (\ref{eq:T1}), we can bound $w_y$ in the end of stage 1 as
\begin{align}
    w_y\le \left(1+1.1/\pi-(w_y\T{1})^2\right)^{\left\lceil\log_{2.56}\frac{\frac{1}{2\pi}}{(w_y\T{1})^2/2.7}\right\rceil}.
\end{align}
Since it initializes as $\norm{w\T{0}}\le 0.1$, we have $w_y\T{1}\le 0.1(1+1.1/\pi)=0.135$. Then, it can be verified that, when $w_y\T{1}\in(0,0.135]$, it holds
\begin{align}
    w_y\le 0.44.
\end{align}

The next is to bound $v-w_x$. Combining the update rules of $v$ and $w_x$ in (\ref{eq:deltav}, \ref{eq:deltawx}), we have
\begin{align}
    \Delta(v-w_x) &\coloneqq (v^{(t+1)}-w_x^{(t+1)})-(v^{(t)}-w_x^{(t)}) \nonumber \\
    &=K(v-w_x)\left(v w_x-1+\frac{\arctan(w_y/w_x)-\frac{w_x w_y}{\norm{w}^2}}{\pi}\right) + K\frac{w_y^2}{v}(-v^2+\frac{v w_y}{\pi\norm{w}^2}).\label{eq:deltavwx1}
\end{align}

Note that 
\begin{align}
    -1\le v w_x-1+\frac{\arctan(w_y/w_x)-\frac{w_x w_y}{\norm{w}^2}}{\pi} \le -1+\frac{\arctan(w_y/w_x)}{\pi},
\end{align}
where the left is due to $vw_x>0$ and  , the right is from $\Delta w_y\ge 0$. When $w_y/w_x\le2.7$, the RHS follows $-1+\frac{\arctan(w_y/w_x)}{\pi}\le -0.6$. So combining both sides tells
\begin{align}
    1+K\left(v w_x-1+\frac{\arctan(w_y/w_x)-\frac{w_x w_y}{\norm{w}^2}}{\pi}\right)\in[-K+1, 0.4]\subset [-0.1,0.4].\label{eq:deltavwx_coff}
\end{align}

Since $\Delta w_y\ge 0$, we have $0\le K\frac{w_y^2}{v}(-v^2+\frac{v w_y}{\pi\norm{w}^2})\le \frac{K}{\pi} w_y\frac{w_y^2}{\norm{w}^2}$. Note that at initialization $w_x\T{0}\le v\T{0}$. Then it is easy to verify that
\begin{align}
    -0.01\le -0.1 (v\T{0}-w\T{0})\le v\T{1}-w\T{1}\le (1+\frac{K}{\pi}-\frac{K}{2})v\T{0}\le 0.082.
\end{align}
Because the coefficient on the positive side in (\ref{eq:deltavwx_coff}) is larger than $0.4>0.1$, it is appropriate to upper bound the $v-w_x$ as
\begin{align*}
    v-w_x &\le  \max\left\{0.082, 0.082\cdot 0.4^T + \sum_{t=1}^T 0.4^{t-1} \frac{K}{\pi} w_y^{(t)}\frac{(w_y^{(t)})^2}{\norm{w^{(t)}}^2}\right\} \\
    &\le \max\left\{0.082, 0.082\cdot 0.4^T + \sum_{t=1}^T 0.4^{t-1} \frac{K}{\pi} w_y^{(t)}\frac{1}{1+\frac{1}{2.7}\left(\frac{1.55}{1+K/\pi}\right)^{2(t-1)}}\right\} \\
    &\le \max\left\{0.082, 0.082\cdot 0.4^T + \sum_{t=1}^T 0.4^{t-1} \frac{1.1\cdot 4.4}{\pi} \frac{1}{1+\frac{1}{2.7}\left(\frac{1.55}{1+1.1/\pi}\right)^{2(t-1)}}\right\},
\end{align*}
where the second inequality is from the different growth ratios of $w_x$ and $w_y$. Note that here we take all $T\ge1$ and pick the largest value of RHS to bound $w_y$. It turns out
\begin{align}
    v-w_x\le 0.17.
\end{align}
Furthermore, to lower bound $v-w_x$, since obviously $|v-w_x|\le 0.17$, it follows
\begin{align}
    v-w_x\ge -0.1\cdot |v-w_x|_{\max} \ge -0.017.
\end{align}

\textbf{Case (II). If $\frac{1}{4\pi}\le vw_x<\frac{1}{2\pi}$ in first step of stage 2:}

Similar to the discussion in Case (I), we are able to compute the number of iterations for $vw_x$ to reach $1/4\pi$. It is at most
\begin{align}
    T_1\le \lceil\log_{2.56}\frac{\frac{1}{4\pi}}{(w_y\T{1})^2/2.7}\rceil. \label{eq:T1_2}
\end{align}

Accordingly, $w_y$ is bounded as
\begin{align}
    w_y \le \left(1+1.1/\pi-(w_y\T{1})^2\right)^{\lceil\log_{2.56}\frac{\frac{1}{4\pi}}{(w_y\T{1})^2/2.7}\rceil}\le 0.37.
\end{align}

For simplicity, we just keep the bounds for $v-w_x$ as in Case (I), as
\begin{align}
    v-w_x\in[-0.017, 0.17].
\end{align}

\textbf{Case (III). If $vw_x<\frac{1}{4\pi}$ in first step of stage 2:}

From the condition, we know $vw_x<\frac{1}{4\pi}$ as well in the last step of stage 1. Since $\Delta w_y>0$ in stage 1, it tells
\begin{align}
    \frac{1}{\pi}\frac{w_x w_y}{\norm{w}^2}<v w_x\le \frac{1}{4\pi},
\end{align}
which means
\begin{align}
    \max\{\frac{w_x}{w_y}, \frac{w_y}{w_x}\}\ge 2+\sqrt{3}.
\end{align}
Since $2+\sqrt{3}>2.7$, if $w_y/w_x\ge 2+\sqrt{3}$, then for time 1, $(v\T{1}, w_x\T{1}, w_y\T{1})$ is already in the stage 2. However, it is not possible because $\norm{w\T{0}}=v\T{0}\le 0.1$, which means $v\T{1} w_x\T{1}$ can not reach $\frac{1}{\pi}\frac{2.7}{1+2.7^2}$.

Therefore, the only possible is $\frac{w_x}{w_y}\ge 2+\sqrt{3}$. In this case, we are able to bound $w_y$ as
\begin{align}
    w_y\le (2-\sqrt{3})w_x\le (2-\sqrt{3})\left(\sqrt{\frac{1}{4\pi}+0.0085^2}+0.0085\right) \le 0.078,
\end{align}
where the second inequality is due to $vw_x\le\frac{1}{4\pi}$ and $v-w_x\ge -0.017$. Note that here we still use the bound of $v-w_x$ from Case (I), although it is loose somehow but it is enough for our analysis.

We leave the analysis of the bound of number of iterations to the end of this section.


\vspace{10pt}
{\centerline{\large{\textbf{Stage 2.}}}}


In the case (I) of stage 1, where the first step in stage 2 is with $v w_x \ge \frac{1}{2\pi}$, it has $v-w_x\in[-0.017, 0.17]$ and $w_y\le 0.44$. In the case (II), where the first step of stage 2 is with $v w_x\in[\frac{1}{4\pi}, \frac{1}{2\pi}]$, it has $v-w_x\in[-0.017, 0.17]$ and $w_y\le 0.37$. In the case (III), where the first step of stage 2 is with $v w_x\in[\frac{1}{4\pi}, \frac{1}{2\pi}]$, it has $v-w_x\in[-0.017, 0.17]$ and $w_y\le 0.078$.











To upper bound $v w_x$ in the first step of stage 2, there are two candidates. One is from the case (I), 
\begin{align}
    v^{(t+1)} w_x^{(t+1)} &= vw_x\left( 1+K(1-v w_x - \frac{\arctan(\frac{w_y}{w_x})-\frac{w_y/w_x}{1+(w_y/w_x)^2}}{\pi}) \right)^2 + K\frac{w_x w_y^2}{v}\left(-v^2+\frac{v w_y}{\pi\norm{w}^2}\right) \nonumber\\
    & ~~~~ + K(v-w_x)^2\left( 1+K(1-v w_x - \frac{\arctan(\frac{w_y}{w_x})-\frac{w_y/w_x}{1+(w_y/w_x)^2}}{\pi}) \right) \nonumber\\
    &\le vw_x\left( 1+K(1-v w_x)\right)^2 + K\frac{w_x w_y^2}{w_x}\left(-vw_x+\frac{w_x w_y}{\pi\norm{w}^2}\right) \nonumber\\
    & ~~~~ + K(v-w_x)^2\left( 1+K(1-v w_x) \right) \nonumber \\
    &\le \frac{1}{2\pi}\left( 1+1.1(1-\frac{1}{2\pi})\right)^2 + 1.1\cdot 0.44^2\left(-\frac{1}{4\pi}+\frac{1}{2\pi}\right) + 1.1\cdot 0.17^2\left( 1+1.1(1-\frac{1}{2\pi}) \right) \nonumber \\
    &\le 0.668,
\end{align}
where we use $v w_x\ge 1/4\pi$, $x/(1+x^2)\le 0.5$ for any $x$. 

One is from the case (II),
\begin{align}
    v^{(t+1)} w_x^{(t+1)} 
    &\le vw_x\left( 1+K(1-v w_x)\right)^2 + K\frac{w_x w_y^2}{w_x}\left(-vw_x+\frac{w_x w_y}{\pi\norm{w}^2}\right) \nonumber\\
    & ~~~~ + K(v-w_x)^2\left( 1+K(1-v w_x) \right) \nonumber \\
    &\le \frac{1}{4\pi}\left( 1+1.1(1-\frac{1}{4\pi})\right)^2 + 1.1\cdot 0.37^2\left(\frac{1}{2\pi}\right) + 1.1\cdot 0.17^2\left( 1+1.1(1-\frac{1}{4\pi}) \right) \nonumber \\
    &\le 0.48,
\end{align}
where we use $v w_x\le 1/4\pi$, $x/(1+x^2)\le 0.5$ for any $x$. 

Therefore, we can see that, in the first step of stage 2,
\begin{align}
    v w_x\le 0.668.
\end{align}



Next we are going to show how the iteration goes in the stage 2. In Case (I), there are three facts:
\begin{enumerate}
    \item $w_y\le 0.44$.
    \item $v-w_x\in[-0.017, 0.17]$.
    \item $vw_x \in[\frac{1}{2\pi}, 0.668]$.
\end{enumerate}
Similarly, in Case (II), there are three facts as well:
\begin{enumerate}
    \item $w_y\le 0.37$.
    \item $v-w_x\in[-0.017, 0.17]$.
    \item $vw_x \in[\frac{1}{4\pi}, \frac{1}{2\pi}]$.
\end{enumerate}

The main idea is to find a basin that any iteration with the above properties (\textit{i.e.}, in the interval) will converge to and then stay in. The method is to iteratively compute the ranges of the variables for several steps, thanks to the narrow range of $K$. Before explicitly computing the ranges, let's write down the computing method, depending on whether or not $v w_x\ge1$.

Consider any iteration with $v w_x\in[m_1,m_2], v-w_x\in[d_1,d_2], w_y\le e$, we compute the bounds of $v^{(t+1)} w_x^{(t+1)}, v^{(t+1)}-w_x^{(t+1)}, w_y^{(t+1)}$ in the following process (naturally assuming $d_1<0<d_2$)
\begin{enumerate}
    \item If $m_1\ge 1$:

    \begin{enumerate}
        \item Compute $w_x\ge \sqrt{m_1+(d_2/2)^2}-d_2/2\triangleq f$.
        \item Compute $\frac{w_y}{w_x}\le e/f\triangleq g$.
        \item Compute $\frac{\arctan(w_y/w_x)-\frac{w_x w_y}{\norm{w}^2}}{\pi}\le \frac{\arctan(g)-g/(1+g^2)}{\pi}\triangleq h$.
        \item Compute $v^{(t+1)} w_x^{(t+1)} \ge m_2(1+1.1(1-m_2-h))^2+1.1(1-m_2-h)\max\{|d_1|,|d_2|\}^2-1.1e^2 m_2$. This is from 
            \begin{align}
                v^{(t+1)} w_x^{(t+1)} &\ge vw_x\left( 1+K(1-v w_x - h) \right)^2 + K\frac{w_x w_y^2}{v}\left(-v^2+\frac{v w_y}{\pi\norm{w}^2}\right) \nonumber\\
                & ~~~~ + K(v-w_x)^2\left( 1+K(1-v w_x - h) \right) \nonumber\\
                &\ge vw_x\left( 1+K(1-v w_x - h) \right)^2 - Kw_y^2\cdot vw_x \nonumber\\
                & ~~~~ + K(v-w_x)^2\left( 1+K(1-v w_x - h) \right) \nonumber.
            \end{align}
        \item Compute $v^{(t+1)} w_x^{(t+1)} \le m_1(1+1.0(1-m_1))^2$. This is due to $x(1+K(1-x))^2$ decreases with $x$ increasing when $x\ge 1$.
        \item Compute $v^{(t+1)} - w_x^{(t+1)} \in [d_1(1+1.1(m_2-1+h)-1.1e^2\cdot(\sqrt{m_2+(d_2/2)^2}+d_2/2)), d_2(1+1.1(m_2-1+h))]$. This is due to 
        \begin{align*}
            \Delta v-\Delta w_x = K(v-w_x)\left(v w_x - 1 +\frac{1}{\pi}(\arctan(\alpha)-\frac{w_x w_y}{\norm{w}^2})\right) + K\frac{w_y^2}{v}\left(-v^2+\frac{v w_y}{\pi\norm{w}^2}\right),
        \end{align*}
        where $vw_x\ge 1$, the last term is between $-Kvw_y^2$ and 0.
        \item Compute $w_y^{(t+1)} \le e\cdot\max\{|j_1|, |j_2|\}$, where
        \begin{align}
            j_1 &= 1 + 1.1\frac{\sqrt{m_1+(d_2/2)^2}+d_2/2}{\sqrt{m_1+(d_2/2)^2}-d_2/2}\cdot(-m_2), \\
            j_2 &= 1 + 1.0\frac{\sqrt{m_1+(d_1/2)^2}-d_1/2}{\sqrt{m_1+(d_1/2)^2}+d_1/2}\cdot(-m_1 + \frac{1}{2\pi}).
        \end{align}
        This is due to 
        \[
            \frac{\Delta w_y}{w_y} = K\frac{v}{w_x}(-vw_x + \frac{1}{\pi}\frac{w_x w_y}{\norm{w}^2}),
        \]
        then we would like to have the smallest value as $j_1-1$ and the largest value as $j_2-1$. Since $w_y$ is always non-negative, taking the maximum absolute value gives the upper bound.
    \end{enumerate}

    \item If $m_2< 1$:

    \begin{enumerate}
        \item Compute $w_x\ge \sqrt{m_1+(d_2/2)^2}-d_2/2\triangleq f$.
        \item Compute $\frac{w_y}{w_x}\le e/f\triangleq g$.
        \item Compute $\frac{\arctan(w_y/w_x)-\frac{w_x w_y}{\norm{w}^2}}{\pi}\le \frac{\arctan(g)-g/(1+g^2)}{\pi}\triangleq h$.
        \item Compute $v^{(t+1)} w_x^{(t+1)} \ge \min_{x\in[m_1, m_2]} x(1+1.0(1-x-h))^2-1.1e^2 x$. Compared with the case of $m_1\ge 1$, we drop the term $1.1(1-m_2-h)\max\{|d_1|,|d_2|\}^2$ because it is possible to have $v-w_x=0$ in some iterations.
        \item Compute $v^{(t+1)} w_x^{(t+1)} \le \max_{x\in[m_1, m_2]} x(1+1.1(1-x))^2+1.1(1-x)\max\{|d_1|,|d_2|\}^2$. Compared with the case of $m_1\ge 1$, we add a term depending on the $|v-w_x|_{\max}$ because it enlarges $vw_x$ in the in-balanced case.
        \item Compute $v^{(t+1)} - w_x^{(t+1)} \in [d_1(1+1.1(m_2-1+h)-1.1e^2\cdot(\sqrt{m_2+(d_2/2)^2}+d_2/2)), d_2(1+1.1(m_2-1+h))]$. In fact, a rigorous left bound should include more terms to select a minimum from. Here it is simple because it keeps $1+K(m_1-1)\ge 0$ in the following computing, so we do not need to worry about the flipping sign of $d_1$ and $d_2$.
        \item Compute $w_y^{(t+1)} \le e\cdot\max\{|j_1|, |j_2|\}$, where $j_1, j_2$ are the same with those in the case of $m_1\ge 1$.
    \end{enumerate}
\end{enumerate}

Therefore, with the above process, we are able to brutally compute the ranges of $v^{(t+1)} w_x^{(t+1)}, v^{(t+1)}-w_x^{(t+1)}, w_y^{(t+1)}$ from the current ranges. Note that this process plays a role of building a mapping from one interval to another interval, which covers all points from the source interval. However, it is loose to some extent because gradient descent is a mapping from a point to another point. The advantage of such a loose method is feasibility of obtaining bounds while losing tightness. To achieve tightness, later we will also include some wisdom in a point-to-point style.

Also note that, a nice way to combine tightness and efficiency in this method is to split and to merge intervals when necessary.

