\textbf{For both Cases (I, II):}

From $I_{16-20}, I_{28}, I_{29}, I_{49-51}, I_{61}, I_{62}$, we can see that it has fallen into an interval $I_f=\{w_y<0.1, v-w_x\in[-0.462,0.148], vw_x\in[0.497,1.34078]\}$. Something special here is that $w_y$ has been much smaller than $w_x$. More broadly, let's define an interval $I_s$ generated by $I_g=\{w_y=0, v-w_x\in[-0.464,0.148], vw_x\in[1,1.5]\}$. Here ``generated'' means
\begin{align}
    I_s = \bigcup_{T\ge t} \{(v\T{T}, w_x\T{T}, w_y\T{T})|(v_t^{(t)}, w_x^{(t)}, w_y^{(t)})\in I_g\}.
\end{align}

Then each element $(v,w_x,w_y)\in I_s$ has the following properties:
\begin{enumerate}
    \item $w_y=0$.
    \item $vw_x\in[0.181,1.5]$.
    \item If $vw_x\le 1$, then $v-w_x\in [-0.735, 0.23]$. If $vw_x>1$, then $v-w_x\in [-0.474, 0.148]$.
\end{enumerate}
The first property is obvious. The third can be proven as follows: for each element $(v, w_x, w_y)\in I_g$, it has $v^{(t+1)}-w_x^{(t+1)}=(v-w_x)\left(1+K(vw_x-1)\right)$, where the ratio $1+K(vw_x-1)\in[1,1+1.1(1.5-1)]$ when $vw_x\in[1,1.5]$. Furthermore, in the proven 2-D case, we have shown that ``if $vw_x>1$ with some mild conditions, then $\frac{v\T{t+2}-w_x\T{t+2}}{v-w_x}\in(-1,1)$''. Actually it can be tighter as $\frac{v\T{t+2}-w_x\T{t+2}}{v-w_x}\in(-0.2,1)$ because here $K\le 1.1$ while the original bound is for $K\le 1.5$. The condition of bounded $|v-w_x|$ can also be verified, the purpose of which is to keep $v,w_x$ always positive. Then the bound $[-0.2,1]$ will tell $v-w_x\in[-0.474,0.148]$ on $vw_x\ge 1$, because
\begin{align*}
    \frac{0.148}{0.474}>0.2,  ~~~~~~\frac{0.474}{0.148}>0.2.
\end{align*}
For the second property, the left bound can be verified as 
\begin{align*}
    \min_{x\in[1,1.5]}x(1+1.1(1-x))^2 + 1.1(1-x)\cdot 0.474^2 &= \bigg(x(1+1.1(1-x))^2 + 1.1(1-x)\cdot 0.474^2\bigg) \bigg|_{x=1.5} \\
    & \ge 0.181.
\end{align*}
The right bound can be verified as
\begin{align*}
    \max_{x\in[0,1]}x(1+1.1(1-x))^2 + 1.1(1-x)*0.735^2 &<1.5.
\end{align*}
After proving these three properties, we would like to bound how far $I_f$ is away from $I_s$. More precisely, the distance is measured by $w_y$. We are going to show $w_y$ decays exponentially.

Remind the update rules in (\ref{eq:deltav}, \ref{eq:deltawx}). Denote $\gamma = \frac{1}{\pi}(\arctan(\alpha)-\frac{w_x w_y}{\norm{w}^2})$ again and $\delta = K\frac{w_y^2}{v}(-v^2+\frac{v w_y}{\pi \norm{w}^2})$, then it is
\begin{align}
    \Delta v &= Kw_x(-vw_x+1)-Kw_x\gamma + \delta, \label{eq:deltavcorr}\\
    \Delta w_x &= Kv(-vw_x+1)-Kv\gamma, \\
    \delta &\in [-Kvw_y^2, 0].
\end{align}

Note that both $\gamma$ and $\delta$ are very small, so we are to show their effects separately, which is enough to be a good approximation.

Consider an iteration where $v^{(t)} w_x^{(t)}>1$ and the corresponding $\gamma^{(t)}$. Let's denote $v^{(t+1)},w_x^{(t+1)}$ as the next parameters with \textbf{no corruption} from $\gamma^{(t)}$. Similarly, we denote $\hat{v}^{(t+1)}, \hat{w_x}^{(t+1)}$ are corrupted with $\gamma^{(t)}$. From the 2-D analysis, we know
\begin{align}
    \frac{v\T{t+2}-w_x\T{t+2}}{v^{(t)}-w_x^{(t)}} = (1+K(v^{(t)} w_x^{(t)}-1))(1+K(v^{(t+1)} w_x^{(t+1)}-1))<1. \label{eq:ratio_nocrpt}
\end{align}
We would like to show, with a small $\gamma^{(t)}$ and ignoring $\delta$,
\begin{align}
    \frac{\hat{v}\T{t+2}-\hat{w_x}\T{t+2}}{v^{(t)}-w_x^{(t)}} = (1+K(v^{(t)} w_x^{(t)}-1+\gamma^{(t)}))(1+K(\hat{v}^{(t+1)} \hat{w_x}^{(t+1)}-1+\gamma^{(t+1)}))\lessapprox 1, \label{eq:ratio_crpt}
\end{align}
where $\gamma^{(t+1)}$ is in time $(t+1)$ accordingly.
The difference of LHS of the above two expressions turns out to be
\begin{align}
    (\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})
    &=
    K\gamma^{(t)} (1+K(v^{(t+1)} w_x^{(t+1)}-1)) \nonumber \\
    &~~~~~ + (1+K(v^{(t)} w_x^{(t)}-1))K(\hat{v}^{(t+1)} \hat{w_x}^{(t+1)} - v^{(t+1)} w_x^{(t+1)}+\gamma^{(t+1)}) + \mathcal{O}(\gamma^2) \nonumber \\
    &=
    K\gamma^{(t)} (1+K(v^{(t+1)} w_x^{(t+1)}-1)) \nonumber \\
    &~~~~~ + K(1+K(v^{(t)} w_x^{(t)}-1))(-K(v^{(t)})^2 \gamma^{(t)}-K(w_x^{(t)})^2 \gamma^{(t)}+\gamma^{(t+1)}) + \mathcal{O}(\gamma^2) \nonumber \\
    &\le K\gamma^{(t)}\bigg(
    1+(1+K(v^{(t)} w_x^{(t)}-1))\big(
    -K(v^{(t)})^2-K(w_x^{(t)})^2+\frac{\gamma^{(t+1)}}{\gamma^{(t)}}
    \big)
    \bigg)+\mathcal{O}(\gamma^2) \nonumber \\
    &\le K\gamma^{(t)}\bigg(
    1+(1+K(v^{(t)} w_x^{(t)}-1))\big(
    -2K v^{(t)} w_x^{(t)} +\frac{\gamma^{(t+1)}}{\gamma^{(t)}}
    \big)
    \bigg)+\mathcal{O}(\gamma^2). \label{eq:diff_ratios}
\end{align}

Since $\frac{\Delta w_x}{w_x} = K\frac{v}{w_x}(-vw_x +1-\gamma)$, we have
\begin{align}
    \frac{w_x^{(t+1)}}{w_x^{(t)}}=1+K\frac{v^{(t)}}{w_x^{(t)}}(-v^{(t)} w_x^{(t)} +1-\gamma^{(t)})<1.
\end{align}
Also we have
\begin{align}
    \frac{\gamma^{(t+1)}}{\gamma^{(t)}} = \frac{\arctan(\frac{w_y^{(t+1)}}{w_x^{(t+1)}})-\frac{w_x^{(t+1)} w_y^{(t+1)}}{\norm{w^{(t+1)}}^2}}{\arctan(\frac{w_y^{(t)}}{w_x^{(t)}})-\frac{w_x^{(t)} w_y^{(t)}}{\norm{w^{(t)}}^2}}.
\end{align}
Since $w_y^{(t+1)}\le w_y^{(t)}$ and
\begin{align}
    \frac{\arctan(mx)-\frac{mx}{1+m^2x^2}}{\arctan(x)-\frac{x}{1+x^2}}\le m^3,\text{  for any $m>0, x>0$},
\end{align}
we have 
\begin{align}
    \frac{\gamma^{(t+1)}}{\gamma^{(t)}}\le \frac{1}{\left(1+K\frac{v^{(t)}}{w_x^{(t)}}(-v^{(t)} w_x^{(t)} +1-\gamma^{(t)})\right)^3}. \label{eq:ratiogamma}
\end{align}

For general $vw_x\in(1,1.5]$, (\ref{eq:ratiogamma}) holds as
\begin{align}
    \frac{\gamma^{(t+1)}}{\gamma^{(t)}}\lessapprox \frac{1}{(1+1.1\frac{\sqrt{1+0.074^2}+0.074}{\sqrt{1+0.074^2}-0.074}(-1.5+1))^3} \le 22. 
\end{align}
Since $1+K(v^{(t)} w_x^{(t)}-1)\le 1+1.1*0.5=1.55$, it is fair to say
\begin{align}
    (\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})\lessapprox  K\gamma^{(t)}(1+1.55*(-2+22)) + \mathcal{O}(\gamma^2) = 35.2\gamma^{(t)} + \mathcal{O}(\gamma^2).
\end{align}
Actually $\gamma^{(t)}$ is bounded by
\begin{align}
     \frac{w_y^{(t)}}{w_x^{(t)}} &\le \frac{0.099}{\sqrt{1+0.074^2}-0.074}=0.1066,\\
    \gamma^{(t)} &\le \frac{\arctan(x)-\frac{x}{1+x^2}}{\pi}\le 2.6\times 10^{-4}.
\end{align}
As a result, 
\begin{align}
    (\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})\lessapprox 0.0084.
\end{align}
Note that this small value is very easy to cover in (\ref{eq:ratio_nocrpt}), requiring
\begin{align}
    1-\frac{v\T{t+2}-w_x\T{t+2}}{v^{(t)}-w_x^{(t)}}\ge 0.0084,
\end{align}
except when $vw_x$ is pretty close to 1. When $vw_x\xrightarrow{} 1$, from the analysis of 2-D case, (derived from the case of $x_{t+1} y_{t+1}\ge x_s^2$)
\begin{align}

    1-\frac{v\T{t+2}-w_x\T{t+2}}{v^{(t)}-w_x^{(t)}} \ge (2K-2)(v^{(t)} w_x^{(t)} -1).
\end{align}
For $(\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})$, denote a function $p(x)$ as
\begin{align}
    p(x) = 1+(1+Kx)\left(-2K(x+1)+\frac{1}{\left(1+K\frac{v}{w_x}(-x)\right)^3}\right),
\end{align}
where $x=v^{(t)} w_x^{(t)} - 1$ in (\ref{eq:diff_ratios}, \ref{eq:ratiogamma}). It is obvious that $p(0)=1+(-2K+1)<0$. When $x$ is small, it turns out
\begin{align}
    p(x) = -2K + 2 + K\left(-2K-1+3\frac{v^{(t)}}{w_x^{(t)}}\right)x + \mathcal{O}(x^2) \label{eq:px0}
\end{align}
As a result, $(\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})<0$ when $v w_x-1=o(K-1)$. What if $vw_x-1=\Omega(K-1)$? Actually, we can get a better bound by a more care analysis, as
\begin{align}
        \frac{(\ref{eq:ratio_crpt})-(\ref{eq:ratio_nocrpt})}{K\gamma^{(t)}}
        &\le 
        1+(1+K(v^{(t)} w_x^{(t)}-1))\big(
        -K(v^{(t)})^2-K(w_x^{(t)})^2+\frac{\gamma^{(t+1)}}{\gamma^{(t)}}
        \big)
        \nonumber\\
        & ~~~~ + K\left[ v^{(t)} w_x^{(t)}(1+K(1-v^{(t)} w_x^{(t)}))^2-1\right],
\end{align}
where the last term is due to $v^{(t+1)} w_x^{(t+1)} \le v^{(t)} w_x^{(t)}(1+K(1-v^{(t)} w_x^{(t)}))^2$. Hence, with this bound, by expanding the last term, (\ref{eq:px0}) becomes
\begin{align}
    p(x) &= -2K + 2 + K\left(-2K-1+3\frac{v^{(t)}}{w_x^{(t)}}\right)x + K(1-2K)x + \mathcal{O}(x^2) \\
    &= -2K+2 + K\left(-4K+3\frac{v^{(t)}}{w_x^{(t)}}\right)x+\mathcal{O}(x^2),
\end{align}
which is definitely negative because 
\begin{align}
    \frac{v^{(t)}}{w_x^{(t)}}\le\frac{\sqrt{1+0.074^2}+0.074}{\sqrt{1+0.074^2}-0.074}<1.16<\frac{4}{3}.
\end{align}

Meanwhile, we are to prove the $\delta$ in (\ref{eq:deltavcorr}) will not make $\tilde{I}_s$ make $v-w_x<-0.474$ starting from $v-w_x\ge -0.462$. First, in the region of $\{vw_x\in[1,1.5], v-w_x\le 0.148\}$, we have $Kvw_y^2\le 1.1\cdot(\sqrt{1.5+0.074^2}+0.074)*0.1^2\le 0.0144$. Also note that in this region with $v-w_x\ge -0.462$, we have
\begin{align}
    \frac{w_y^{(t+1)}}{w_y}\le 1-\frac{\sqrt{1+0.231^2}-0.231}{\sqrt{1+0.231^2}+0.231}=0.37.
\end{align}
Hence $Kv(w_y^{(t)})^2+Kv(w_y^{(t+1)})^2\le 0.0144*(1+0.37^2)=0.0164$. Since $|v\T{t+2}-w\T{t+2}|< |v^{(t)}-w^{(t)}|$ if there is no $\delta$, we shall see that there is no need to discuss the case of $v-w_x\ge -0.462+0.0164=-0.4456$ because it still holds $v^{(t+1)} -w_x^{(t+1)}>-0.462$. When $v^{(t)}-w_x^{(t)}\in[-0.462, -0.4456]$, we shall see that in (\ref{eq:xybalance}), after adding the term of $\delta$ in $v$,
\begin{align}
    \frac{v\T{t+2}-w_x\T{t+2}}{v^{(t)}-w_x^{(t)}}\le 1-(1+K(v w_x -1))\cdot K w_x \delta,
\end{align}
which means the absolute value of $v-w_x$ decays at least by a margin depending on $\delta$. After multiplying the current difference $v^{(t)}-w_x^{(t)}$ on both side, it gives
\begin{align}
    (v\T{t+2}-w_x\T{t+2})-(v^{(t)}-w_x^{(t)}) \ge v^{(t)} w_x^{(t)} w_x^{(t)} \delta.
\end{align}
Note that here $v\T{t+2}-w_x\T{t+2}$ does not include $\delta^{(t)}$ and $\delta^{(t+1)}$. As stated above, we have $\frac{\delta^{(t+1)}}{\delta^{(t)}}\le 0.37^2\le 0.16$ due to the decay of $w_y$. So it is safe to say $\delta^{(t)} + \delta^{(t+1)}\ge 1.16\delta^{(t)}$. Combining with the above inequality, it gives
\begin{align}
    (v\T{t+2}-w_x\T{t+2})-(v^{(t)}-w_x^{(t)}) +\delta^{(t)} + \delta^{(t+1)} \ge (v^{(t)} w_x^{(t)} w_x^{(t)} + 1.16)\delta^{(t)}, \label{eq:deltat1}
\end{align}
where
\begin{align}
    v^{(t)} w_x^{(t)} w_x^{(t)} + 1.16 \le  vw_x \cdot (\sqrt{vw_x +(\frac{0.4456}{2})^2}-\frac{0.4456}{2})+1.16 \le 0.6.
\end{align}
Furthermore, from our previous discussion, $w_y\T{t+2}<w_y\T{t+2}$ gives that the sum of (\ref{eq:deltat1}) is bounded by
\begin{align}
