For a matrix factorization problem, assume $\mathbf{X}\mathbf{Y}=\mathbf{C}$.
Consider SVD of both matrices as $\mathbf{X} = \sum_{i=1}^{\min\{m,p\}} \sigma_{x,i} u_{x,i} v_{x,i}^\top$ and $\mathbf{Y} = \sum_{i=1}^{\min\{p,q\}} \sigma_{y,i} u_{y,i} v_{y,i}^\top$, where both groups of $\sigma_{\cdot,i}$'s are in descending order and both top singular values $\sigma_{x,1}$ and $\sigma_{y,1}$ are unique. Also assume $v_{x,1}^\top u_{y,1}\neq 0$. Then the leading eigenvector of the loss Hessian is $\Delta=\text{vec}(C_1 u_{x,1}u_{y,1}^\top, C_2 v_{x,1}v_{y,1}^\top)$ with $C_1=\frac{\sigma_{y,1}}{\sqrt{\sigma_{x,1}^2+\sigma_{y,1}^2}}, C_2=\frac{\sigma_{x,1}}{\sqrt{\sigma_{x,1}^2+\sigma_{y,1}^2}}$. Denote $f_\Delta$ as the 1D function at the cross section of the loss landscape and the line following the direction of $\Delta$ passing $\text{vec}(\Delta\mathbf{X}, \Delta\mathbf{Y})$. Then, at the minima of $f_\Delta$, it satisfies
\begin{align}
    3[f_\Delta^{(3)}]^2 - f_\Delta^{(2)}f_\Delta^{(4)}>0.
\end{align}

To obtain the direction of the leading Hessian eigenvector at parameters $(\mathbf{X}, \mathbf{Y})$, consider a small deviation of the parameters as $(\mathbf{X}+\Delta \mathbf{X},\mathbf{Y}+\Delta \mathbf{Y})$. With $\mathbf{X}\mathbf{Y}=\mathbf{C}$, evaluate the loss function as
\begin{align}
    L(\mathbf{X}+\Delta \mathbf{X},\mathbf{Y}+\Delta \mathbf{Y}) &= 
    \frac{1}{2}\norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}+\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2.
\end{align}
Expand these terms and split them by orders of $\Delta\mathbf{X},\Delta\mathbf{Y}$ as follows:
\begin{align}
    \Theta(\norm{\Delta\mathbf{X}}^2+\norm{\Delta\mathbf{Y}}^2):& 
    ~~~~~\frac{1}{2}\norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2, \label{eq:mfloss_2nd}\\
    \Theta(\norm{\Delta\mathbf{X}}^3+\norm{\Delta\mathbf{Y}}^3):& 
    ~~~~~\langle \Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}, \Delta\mathbf{X}\Delta\mathbf{Y} \rangle, \label{eq:mfloss_3rd}\\
    \Theta(\norm{\Delta\mathbf{X}}^4+\norm{\Delta\mathbf{Y}}^4):& 
    ~~~~~\frac{1}{2}\norm{\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2. \label{eq:mfloss_4th}
\end{align}
From the second-order terms, the leading eigenvector of $\nabla^2 L$ is the solution of 
\begin{align}
    \text{vec}(\Delta\mathbf{X}, \Delta\mathbf{Y}) = \mathop{\mathrm{arg\,max}}_{\norm{\Delta\mathbf{X}}_F^2+\norm{\Delta\mathbf{Y}}_F^2 = 1}\norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2.
\end{align}
Since both the top singular values of $\mathbf{X},\mathbf{Y}$ are unique, the solution shall have both $\Delta\mathbf{X}, \Delta\mathbf{Y}$ of rank 1. Actually the solution is (here for simplicity we eliminate the sign of both)
\begin{align}
    \Delta\mathbf{X} = \frac{\sigma_{y,1}}{\sqrt{\sigma_{x,1}^2+\sigma_{y,1}^2}} u_{x,1}u_{y,1}^\top, ~~~~\Delta\mathbf{Y}=\frac{\sigma_{x,1}}{\sqrt{\sigma_{x,1}^2+\sigma_{y,1}^2}} v_{x,1}v_{y,1}^\top.
\end{align}
Equipped with the top eigenvector of Hessian, $\text{vec}(\Delta\mathbf{X}, \Delta\mathbf{Y})$, we consider the 1-D function $f_{\Delta}$ generated by the cross-section of the loss landscape and the eigenvector, passing the minima $(\mathbf{X},\mathbf{Y})$. 

Define the function as 
\begin{align}
    f_{\Delta}(\mu) = L(\mathbf{X}+\mu\Delta\mathbf{X}, \mathbf{Y}+\mu\Delta\mathbf{Y}), ~~~~\mu\in\mathbb{R}.
\end{align}
Then, around $\mu=0$, we have
\begin{align}
    f_{\Delta}(\mu) = \frac{1}{2}\norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2\cdot \mu^2 + \langle \Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}, \Delta\mathbf{X}\Delta\mathbf{Y} \rangle \cdot \mu^3 + 
    \frac{1}{2}\norm{\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2 \cdot \mu^4.
\end{align}
Therefore, the several order derivatives of $f_{\Delta}(\mu)$ at $\mu=0$ can be obtained from Taylor expansion as
\begin{align}
    f^{(2)}_\Delta (0) &= \norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2, \\
    f^{(3)}_\Delta (0) &= 6\langle \Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}, \Delta\mathbf{X}\Delta\mathbf{Y} \rangle, \\
    f^{(4)}_\Delta (0) &= 12\norm{\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2.
\end{align}
Then we compute the condition of stable oscillation of 1-D function as
\begin{align}
    \big[3[f_\Delta^{(3)}]^2 - f_\Delta^{(2)}f_\Delta^{(4)}\big] (0)
    &=
    108 \langle \Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}, \Delta\mathbf{X}\Delta\mathbf{Y} \rangle^2 - 12 \norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2 \norm{\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2 \\
    &= 
    96 \norm{\Delta\mathbf{X}\mathbf{Y} + \mathbf{X}\Delta\mathbf{Y}}_F^2 \norm{\Delta\mathbf{X}\Delta\mathbf{Y}}_F^2 >0,
\end{align}
because all of $\Delta\mathbf{X}\mathbf{Y}, \mathbf{X}\Delta\mathbf{Y}, \Delta\mathbf{X}\Delta\mathbf{Y}$ are parallel to $u_{x,1} v_{y,1}^\top$ and $v_{x,1}^\top u_{y,1}\neq 0$.

