    \\
    &~~~~ 

        -\eta \cc{2}_t \mathbb{I}_{1}^\top\mathbf{Y}_0\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1} 
        -\eta \cc{2}_t \cc{1}_t\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1} 

    \\
    &~~~~ 

        - \eta\mathbb{I}_{\ge2}^\top \mathbf{M}_{t}\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}\cc{5}_t 
        - \eta\mathbb{I}_{\ge2}^\top \mathbf{M}_{t}\mathbb{I}_{1}\cc{5}_t\cc{5}_t 







    \\
    &~~~~


        - \eta \cc{4}_t\cc{3}_t^\top\mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1}








    \\
    &~~~~
        + \eta^2 \mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_{1}
        (\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_1^\top+\cc{5}_t)
        (\mathbb{I}_{1}^\top\mathbf{Y}_0\mathbb{I}_{1}+\cc{1}_t)\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1}
    \\
    &=
        \mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_{1}
        - \eta\mathbb{I}_{\ge2}^\top \mathbf{M}_{t}\mathbb{I}_{1}\left(\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}+\cc{5}_t\right)^2
        - \eta \mathbb{I}_{\ge2}^\top \mathbf{Y}_0 \mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top \mathbf{Y}_0\mathbb{I}_{\ge 2}\mathbb{I}_{\ge 2}^\top\mathbf{M}_{t} \mathbb{I}_{1}
        \\
        &~~~~
        - \eta \mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1}\underbrace{\left(\mathbb{I}_{\ge2}^\top \mathbf{Y}_0 \mathbb{I}_{\ge2}\cc{3}_t^\top+\cc{2}_t \mathbb{I}_{1}^\top\mathbf{Y}_0\mathbb{I}_{1}+\cc{2}_t \cc{1}_t+ \cc{4}_t\cc{3}_t^\top\right)}_{=\mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)^\top\mathbb{I}_{1}}
        \\
        &~~~~
        + \eta^2 \mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_{1}
        (\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_1^\top+\cc{5}_t)
        (\mathbb{I}_{1}^\top\mathbf{Y}_0\mathbb{I}_{1}+\cc{1}_t)\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1}
\end{align*}

\begin{align*}
    \mathbb{I}_{1}^\top\mathbf{M}_{t+1} \mathbb{I}_{1}
    &\approx
        \mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1}

        - \eta\mathbb{I}_{1}^\top \mathbf{M}_{t}\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}\mathbb{I}_{1}^\top \mathbf{Z}_0^\top\mathbb{I}_{1}
        - \eta\mathbb{I}_{1}^\top \mathbf{M}_{t}\mathbb{I}_{1}\cc{5}_t\mathbb{I}_{1}^\top \mathbf{Z}_0^\top\mathbb{I}_{1}

    \\
    &~~~~ 

        - \eta \mathbb{I}_{1}^\top \mathbf{Y}_0 \mathbb{I}_{1}\mathbb{I}_{1}^\top \mathbf{Y}_0\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1} 
        - \eta \mathbb{I}_{1}^\top \mathbf{Y}_0 \mathbb{I}_{1}\cc{1}_t\mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1}

    \\
    &~~~~ 

        - \eta \cc{1}_t\mathbb{I}_{1}^\top \mathbf{Y}_0\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1} 
        - \eta \cc{1}_t\cc{1}_t\mathbb{I}_{1}^\top\mathbf{M}_{t} \mathbb{I}_{1}

    \\
    &~~~~ 

        - \eta\mathbb{I}_{1}^\top \mathbf{M}_{t}\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}\cc{5}_t 
        - \eta\mathbb{I}_{1}^\top \mathbf{M}_{t}\mathbb{I}_{1}\cc{5}_t\cc{5}_t 



















    \\
    &~~~~ 
        + \eta^2 \mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1}
        (\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}+\cc{5}_t)
        (\mathbb{I}_{1}^\top\mathbf{Y}_0\mathbb{I}_{1}+\cc{1}_t)
        \mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1}
\end{align*}

\begin{align*}
    \mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)^\top\mathbb{I}_{1}
    &=
        \mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)^\top\mathbb{I}_{1}
    \\
    &~~~~
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{\ge2}\cc{3}_t^\top
        -\eta(\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}+\cc{4}_t)\mathbb{I}_{\ge2}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{1}(\cc{1}_t+\sigma_1\alpha) 
        -\eta\cc{2}\mathbb{I}_{1}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        +\eta^2\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        +\eta^2\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{1}\mathbb{I}_{1}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &=
        \mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)^\top\mathbb{I}_{1}
    \\
    &~~~~

        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{Z}_0\mathbb{I}_{\ge2}\cc{3}_t^\top
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}^\top\cc{7}_t\cc{3}_t^\top
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{\ge2}^\top\cc{8}_t\cc{3}_t^\top
    \\
    &~~~~

        -\eta(\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}+\cc{4}_t)\mathbb{I}_{\ge2}^\top\mathbf{Z}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
        -\eta(\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}+\cc{4}_t)\cc{7}_t^\top \mathbb{I}_{1}^\top \mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        -\eta(\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}+\cc{4}_t)\cc{8}_t^\top \mathbb{I}_{\ge2}^\top \mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~

        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}(\cc{1}_t+\sigma_1\alpha) 
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}\cc{5}_t(\cc{1}_t+\sigma_1\alpha) 
        \\&~~~~
        -\eta\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{\ge2}\cc{6}_t(\cc{1}_t+\sigma_1\alpha) 
    \\
    &~~~~

        -\eta\cc{2}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1}\mathbb{I}_{1}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
        -\eta\cc{2}\cc{5}_t\mathbb{I}_{1}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
        -\eta\cc{2}\cc{6}_t^\top\mathbb{I}_{\ge2}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        +\eta^2\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &~~~~
        +\eta^2\mathbb{I}_{\ge2}^\top\mathbf{M}_t(\mathbf{Z}_0+\Delta\mathbf{Z}_t)\mathbb{I}_{1}\mathbb{I}_{1}^\top(\mathbf{Z}_0+\Delta\mathbf{Z}_t)^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &\approx 
    \mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)^\top\mathbb{I}_{1}
    \\
    &~~~~







        -\eta\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{Z}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{M}_t^\top\mathbb{I}_{1}



    \\
    &~~~~



        -\eta(\cc{1}_t+\sigma_1\alpha)(\cc{5}_t+\frac{\sigma_1}{\alpha})\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}

    \\
    &~~~~




        -\eta\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{1}\underbrace{\left( \cc{2}\mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1} + \cc{2}\cc{5}_t\mathbb{I}_{1}^\top + (\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}+\cc{4}_t)\cc{7}_t^\top \right)}_{=\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}}








    \\
    &~~~~

        +\eta^2\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}
        ( \mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1} + \cc{5}_t)
        ( \mathbb{I}_{1}^\top\mathbf{Z}_0\mathbb{I}_{1} + \cc{5}_t)
        \mathbb{I}_{1}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
    \\
    &=
        \mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_t\right)^\top\mathbb{I}_{1}
        \\
        &~~~~
            -\eta\left((\cc{1}_t+\sigma_1\alpha)(\cc{5}_t+\frac{\sigma_1}{\alpha})+\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{1}(1-\eta(\cc{5}_t+\frac{\sigma_1}{\alpha})^2)\right)\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_{1}
        \\
        &~~~~
            -\eta\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{Z}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{M}_t^\top\mathbb{I}_{1}
\end{align*}

\begin{align*}
    \mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)^\top\mathbb{I}_{\ge2}
    &\approx
        \mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_t\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_t\right)^\top\mathbb{I}_{\ge2}
        \\
        &~~~~
            -\eta\left((\cc{1}_t+\sigma_1\alpha)(\cc{5}_t+\frac{\sigma_1}{\alpha})+\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{1}(1-\eta(\cc{1}_t+\sigma_1\alpha)^2)\right)\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{\ge2}
        \\
        &~~~~
            -\eta\mathbb{I}_{\ge2}^\top\mathbf{Y}_0\mathbb{I}_{\ge2}\mathbb{I}_{\ge2}^\top\mathbf{Z}_0\mathbb{I}_{\ge2}\mathbb{I}_{1}^\top\mathbf{M}_t^\top\mathbb{I}_{\ge2}
\end{align*}


Therefore, we have built a $4\times4$ matrix to characterize the dynamics of $\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_1$, $\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{\ge2}$, $\mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)^\top\mathbb{I}_{1}$, $\mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)^\top\mathbb{I}_{\ge2}$ as, for $\forall p\in\{2,3,\dots,d\}$
\begin{gather*}
    \begin{bmatrix}
        [\mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)^\top\mathbb{I}_{1}]_p\\
        [\mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)^\top\mathbb{I}_{\ge2}]_p\\
        [\mathbb{I}_{\ge2}^\top\mathbf{M}_{t+1}\mathbb{I}_1]_p \\
        [\mathbb{I}_{1}^\top\mathbf{M}_{t+1}\mathbb{I}_{\ge2}]_p
    \end{bmatrix}
    \leftarrow 
    \mathbf{Q}_{\alpha,\eta,p}(y_t, z_t)
    \begin{bmatrix}
        [\mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t}\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t}\right)^\top\mathbb{I}_{1}]_p\\
        [\mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t}\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t}\right)^\top\mathbb{I}_{\ge2}]_p\\
        [\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1]_p \\
        [\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}]_p
    \end{bmatrix},\\
    \mathbf{Q}_{\alpha,\eta,p}(y_t, z_t)
    \triangleq
    \begin{bmatrix}
        1 & 0 & u_{1,t} & -\eta\sigma_p^2 \\
        0 & 1 & -\eta\sigma_p^2 & u_{2,t} \\
        -\eta(y_t z_t-\sigma_1^2) & 0 & w_{1,t} & 0 \\
        0 & -\eta(y_t z_t-\sigma_1^2) & 0 & w_{2,t}
    \end{bmatrix},
    \\
    y_t \triangleq \cc{1}_t+\sigma_1\alpha, ~~~~ z_t\triangleq \cc{5}_t+\nicefrac{\sigma_1}{\alpha_p},\\
    u_{1,t}\triangleq -\eta\left( y_t z_t + (y_t z_t-\sigma_1^2)(1-\eta z_t^2) \right),\\
    u_{2,t}\triangleq -\eta\left( y_t z_t + (y_t z_t-\sigma_1^2)(1-\eta y_t^2) \right),\\
    w_{1,t}\triangleq 1-\eta z_t^2-\eta\sigma_p^2\alpha^2+\eta^2 y_t z_t (y_t z_t - \sigma_1^2), \\
    w_{2,t}\triangleq 1-\eta y_t^2-\eta\nicefrac{\sigma_p^2}{\alpha^2}+\eta^2 y_t z_t (y_t z_t - \sigma_1^2),
\end{gather*}
where $[\cdot]_p$ means the $p$-th value in a vector.

Recall we have $y_t, z_t$ following the training dynamics of minimizing $\frac{1}{2}(\sigma_1^2-y z)^2$ with learning rate $\eta>\frac{1}{\sigma_1^2}$, where leads to $y=z=\gamma_i$, with $\gamma_i$ ($i=1,2$) are the two roots of solving the 1-D function~(\ref{eq:1d_orbit}) as $\delta$. We denote their corresponding $\mathbf{Q}$ as
$\mathbf{Q}_{\alpha,\eta,p}(\gamma_1, \gamma_1)$ and $\mathbf{Q}_{\alpha,\eta,p}(\gamma_2, \gamma_2)$. We assume that their product $\mathbf{Q}_{\alpha,\eta,p}(\gamma_2, \gamma_2)\mathbf{Q}_{\alpha,\eta,p}(\gamma_1, \gamma_1)$ is diagonalizable with all eigenvalues falling into $(-1,1)$, which means its infinite power $\lim_{k\rightarrow \infty}[\mathbf{Q}_{\alpha,\eta,p}(\gamma_2, \gamma_2)\mathbf{Q}_{\alpha,\eta,p}(\gamma_1, \gamma_1)]^{k} = 0$. Meanwhile, due to the 2-D analysis of dynamics of GD on $\frac{1}{2}(\sigma_1^2-y z)^2$, we know $(y_t, z_t)\rightarrow \{(\gamma_1,\gamma_1), (\gamma_2, \gamma_2)\}$ exponentially after finite steps. This is equivalent to say, there exists finite $t_0$, for any $t>t_0$, there exists $i\in\{1,2\}$, constant $C_0$ and $\mathbf{R}_t\in\mathbb{R}^{4\times4}$, such that
\begin{gather*}
    \mathbf{Q}_{\alpha,\eta,p}(y_{t+1}, z_{t+1})\mathbf{Q}_{\alpha,\eta,p}(y_t, z_t) = \mathbf{Q}_{\alpha,\eta,p}(\gamma_{3-i}, \gamma_{3-i})\mathbf{Q}_{\alpha,\eta,p}(\gamma_i, \gamma_i) + \mathbf{R}_{t}, ~~~~ \norm{\mathbf{R}_{t}}\le C_0 r^t, ~~~0<r<1.
\end{gather*}
The decay rate $r$ can be estimated via local analysis around the convergence orbit.
As a result, it is safe to say $\lim_{t\rightarrow\infty}\mathbf{Q}_{\alpha,\eta,p}(y_{2t+1}, z_{2t+1})\mathbf{Q}_{\alpha,\eta,p}(y_{2t}, z_{2t})=0$, which means all of $\mathbb{I}_{\ge2}^\top\mathbf{M}_t\mathbb{I}_1$, $\mathbb{I}_{1}^\top\mathbf{M}_t\mathbb{I}_{\ge2}$, $\mathbb{I}_{\ge2}^\top\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)\left(\mathbf{Y}_0+\Delta\mathbf{Y}_{t+1}\right)^\top\mathbb{I}_{1}$, $\mathbb{I}_{1}^\top\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)\left(\mathbf{Z}_0+\Delta\mathbf{Z}_{t+1}\right)^\top\mathbb{I}_{\ge2}$ exponentially go to zero.

There is one concern here: what happens before $t_0$? More concretely, $t_0$ is dependent of $\nicefrac{1}{\epsilon}$ because it requires more steps (intuitively proportional to $\log\nicefrac{1}{\epsilon}$) to increase to a certain value from a small $\epsilon$. Assuming $t_0\sim \log\nicefrac{1}{\epsilon}$ holds, the product $\{\mathbf{Q}_{\alpha,\eta,p}(y_{2t+1}, z_{2t+1})\mathbf{Q}_{\alpha,\eta,p}(y_{2t}, z_{2t})\}_{t\ge 1}$ gives a (loose) upper bound with the norm of products grows exponentially with time $\log\nicefrac{1}{\epsilon}$, which introduces $\nicefrac{1}{\epsilon}$ to the upper bound of $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1}$ and $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$, breaking the assumption of the norms staying in $\mathcal{O}(\epsilon)$. Fortunately, there are two aspects to resolve this. Firstly, with initialization $\epsilon$ small enough, for a relative long time, $\mathbf{Q}_{\alpha,\eta,p}(y_{2t+1}, z_{2t+1})\mathbf{Q}_{\alpha,\eta,p}(y_{2t}, z_{2t})$ is approximately having eigenvalues bounded by 1. More precisely, $\mathbf{Q}$ and the product are
\begin{gather}
    \mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)
    \approx 
    \begin{bmatrix}
        1 & 0 & -\eta\sigma_1^2 & -\eta\sigma_p^2 \\
        0 & 1 & -\eta\sigma_p^2 & -\eta\sigma_1^2 \\
        0 & 0 & 1-\eta \nicefrac{\sigma_1^2}{\alpha^2}-\eta\sigma_p^2\alpha^2 & 0 \\
        0 & 0 & 0 & 1-\eta \sigma_1^2\alpha^2-\eta\nicefrac{\sigma_p^2}{\alpha^2}
    \end{bmatrix},
    \\
    \Lambda(\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot))
    =
    \{
        1, 1, (1-\eta \nicefrac{\sigma_1^2}{\alpha^2}-\eta\sigma_p^2\alpha^2)^2, (1-\eta \sigma_1^2\alpha^2-\eta\nicefrac{\sigma_p^2}{\alpha^2})^2,
    \}
    \label{eq:quasi_q_lambda}
\end{gather}
where the eigenvalues in $\Lambda$ are upper bounded by 1, if assuming $\eta(\nicefrac{\sigma_1^2}{\alpha^2}+\sigma_p^2\alpha^2)<2$ and $1-\eta \sigma_1^2\alpha^2-\eta\nicefrac{\sigma_p^2}{\alpha^2}<2$. As a result, in these steps, $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1}$ and $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$ stay in $\mathcal{O}(\epsilon)$ due to $\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)$ is a semi-convergent matrix. Secondly, the eigenvectors of $\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)\mathbf{Q}_{\alpha,\eta,p}(\cdot, \cdot)$ corresponding to eigenvalue 1 are $[1,0,0,0]^\top$ and $[0,1,0,0]^\top$, which means $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1}$ and $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$ are decaying exponentially. Therefore, smaller $\epsilon$ strengthens the assumption of $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1}$ and $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$ staying in $\mathcal{O}(\epsilon)$ instead of breaking it.

Also note that $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t+1} \mathbb{I}_{\ge2}}\lessapprox\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t} \mathbb{I}_{\ge2}}\cdot\max\{ |1-\eta\sigma_2\left( \alpha^2 + \nicefrac{1}{\alpha^2} \right)|, |1-\eta\sigma_{d-1}\left( \alpha^2 + \nicefrac{1}{\alpha^2} \right)| \}$, so $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t+1} \mathbb{I}_{\ge2}}$ decays exponentially.

Since all of $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t}\mathbb{I}_1}$, $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$ and $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t+1} \mathbb{I}_{\ge2}}$ decay exponentially after some steps, all of them are have the sum upper-bounded, which means $\norm{\cc{2}_t}, \norm{\cc{3}_t}, \norm{\cc{4}_t}, \norm{\cc{6}_t}, \norm{\cc{7}_t}, \norm{\cc{8}_t}$ stay in $\mathcal{O}(\epsilon)$.

To summarize, it holds
\begin{enumerate}
    \item $\norm{\cc{2}_t}, \norm{\cc{3}_t}, \norm{\cc{4}_t}, \norm{\cc{6}_t}, \norm{\cc{7}_t}, \norm{\cc{8}_t}$ stay in $\mathcal{O}(\epsilon)$.
    \item $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{\ge2}}$ and $\norm{\mathbb{I}_{\ge2}^\top\mathbf{M}_{t+1} \mathbb{I}_{\ge2}}$ decays to zero.
    \item $\norm{\mathbb{I}_{1}^\top\mathbf{M}_{t}\mathbb{I}_{1}}$ stays in a period-2 orbit.
\end{enumerate}
